#!/bin/bash
# Nsight Compute stall breakdown of one kernel launch of any program, on the homelab with the trainer paused (tools/gpu_window.sh).
#   tools/ncu_kernel.sh <kernel-regex> <launch-skip> <program and arguments...>        (the program path is relative to ~/forgeinfer/src)
#   FORGE_TPB=256 tools/ncu_kernel.sh matvec_residual_q8_kernel_6 60 ./target/release/forge gpu-bench MODEL --q8 --tokens 16
KEY="$HOME/.ssh/id_ed25519"
HOST="user@homelab"
K="$1"; SKIP="$2"; shift 2
M="gpu__time_duration.sum,sm__cycles_elapsed.avg.per_second,dram__throughput.avg.pct_of_peak_sustained_elapsed,l1tex__throughput.avg.pct_of_peak_sustained_elapsed,sm__warps_active.avg.pct_of_peak_sustained_active,launch__registers_per_thread,launch__grid_size,launch__block_size,launch__occupancy_limit_shared_mem,launch__occupancy_limit_registers,smsp__inst_executed.sum,smsp__warps_active.avg.per_cycle_active,"
M+="smsp__warp_issue_stalled_barrier_per_warp_active.pct,smsp__warp_issue_stalled_long_scoreboard_per_warp_active.pct,smsp__warp_issue_stalled_short_scoreboard_per_warp_active.pct,smsp__warp_issue_stalled_mio_throttle_per_warp_active.pct,smsp__warp_issue_stalled_math_pipe_throttle_per_warp_active.pct,smsp__warp_issue_stalled_wait_per_warp_active.pct,smsp__warp_issue_stalled_lg_throttle_per_warp_active.pct,smsp__warp_issue_stalled_not_selected_per_warp_active.pct,smsp__warp_issue_stalled_selected_per_warp_active.pct,smsp__warp_issue_stalled_dispatch_stall_per_warp_active.pct,smsp__warp_issue_stalled_no_instruction_per_warp_active.pct,smsp__warp_issue_stalled_branch_resolving_per_warp_active.pct,smsp__warp_issue_stalled_membar_per_warp_active.pct,smsp__warp_issue_stalled_drain_per_warp_active.pct,smsp__warp_issue_stalled_sleeping_per_warp_active.pct"
exec ssh -i "$KEY" -o BatchMode=yes -o IdentitiesOnly=yes -o ConnectTimeout=10 "$HOST" "cd ~/forgeinfer/src; export FORGE_TPB=${FORGE_TPB:-128}; bash tools/gpu_window.sh sudo -n --preserve-env=FORGE_TPB \$HOME/cuda-13.2.0/bin/ncu --clock-control none --kernel-name regex:'$K' --launch-skip $SKIP --launch-count 1 --metrics $M $* 2>&1 | grep -E 'Duration|per_second|pct|\.sum|per_cycle|launch__|^  [a-z_0-9]+ \(' | grep -v '^run '"
